\toprule
\textbf{Benchmark} & \textbf{$G \geq 0.80$} & \textbf{$G \geq 0.90$} & \textbf{$G \geq 0.95$} & \textbf{IRT items} & \textbf{Ratio} \\
\midrule
MMLU      & 414  & 1,240 & 2,680 & 116 & 4.4$\times$ \\
ARC-C     & ---  & ---   & ---   & --- & 4.7$\times$ \\
GSM8K     & 580  & ---   & ---   & --- & 3.1$\times$ \\
